'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat32Array = require( '@stdlib/assert/is-same-float32array' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var Float32Array = require( '@stdlib/array/float32' );
var cinvf = require( './../lib/assign.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cinvf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the inverse of a single-precision complex floating-point number', function test( t ) {
	var expected;
	var out;
	var v;

	out = new Float32Array( 2 );
	v = cinvf( 2.0, 4.0, out, 1, 0 );

	expected = new Float32Array( [ 0.1, -0.2 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cinvf( 2.0, 4.0, out, 2, 0 );

	expected = new Float32Array( [ 0.1, 0.0, -0.2, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cinvf( 2.0, 4.0, out, 2, 1 );

	expected = new Float32Array( [ 0.0, 0.1, 0.0, -0.2 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cinvf( 2.0, 4.0, out, -2, 3 );

	expected = new Float32Array( [ 0.0, -0.2, 0.0, 0.1 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function computes a complex inverse', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cinvf( 2.0, 2.0, out, 1, 0 );

	expected = new Float32Array( [ 0.25, -0.25 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 4.0, 0.0, out, 1, 0 );

	expected = new Float32Array( [ 0.25, -0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 0.0, 2.0, out, 1, 0 );

	expected = new Float32Array( [ 0.0, -0.5 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function may overflow', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cinvf( 5.0e-40, 5.0e-40, out, 1, 0 );

	expected = new Float32Array( [ PINF, NINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( -5.0e-40, 5.0e-40, out, 1, 0 );

	expected = new Float32Array( [ NINF, NINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( -5.0e-40, -5.0e-40, out, 1, 0 );

	expected = new Float32Array( [ NINF, PINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 5.0e-40, -5.0e-40, out, 1, 0 );

	expected = new Float32Array( [ PINF, PINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 0.0, 5.0e-40, out, 1, 0 );

	expected = new Float32Array( [ 0.0, NINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 0.0, -5.0e-40, out, 1, 0 );

	expected = new Float32Array( [ 0.0, PINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 5.0e-40, 0.0, out, 1, 0 );

	expected = new Float32Array( [ PINF, -0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( -5.0e-40, 0.0, out, 1, 0 );

	expected = new Float32Array( [ NINF, -0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'if a real or imaginary component is `NaN`, all components are `NaN`', function test( t ) {
	var out;

	out = new Float32Array( 2 );
	cinvf( NaN, 3.0, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( 5.0, NaN, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cinvf( NaN, NaN, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );

	t.end();
});
